CREATE OR REPLACE FUNCTION public.has_permission(permission text,bid uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.staff_assignments s WHERE s.user_id=auth.uid() AND (s.role='super_admin' OR (CASE s.role WHEN 'listing_moderator' THEN permission IN ('claims.review','verification.review','reviews.moderate','listings.moderate','audit.read') WHEN 'support' THEN permission IN ('claims.read','reviews.read') WHEN 'sales' THEN permission IN ('listings.read') WHEN 'content_manager' THEN permission IN ('listings.read','catalogue.read','content.manage') WHEN 'finance' THEN permission IN ('entitlements.read','audit.read','commerce.manage') ELSE false END) AND (s.city IS NULL AND s.category IS NULL OR bid IS NOT NULL AND EXISTS(SELECT 1 FROM public.businesses b WHERE b.id=bid AND (s.city IS NULL OR s.city=b.city) AND (s.category IS NULL OR s.category=b.category))))); $$;
CREATE OR REPLACE FUNCTION public.commerce_action(kind text,payload jsonb,decision_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid; bid uuid; sid uuid; lim integer; used integer; BEGIN
IF length(trim(decision_reason))<5 OR length(payload::text)>20000 THEN RAISE EXCEPTION 'A reason and valid record required'; END IF;
IF kind='redeem' THEN SELECT o.business_id,o.usage_limit INTO bid,lim FROM public.merchant_offers o WHERE o.id=(payload->>'offer_id')::uuid AND approved AND status='active' AND starts_at<=now() AND ends_at>now() FOR UPDATE; IF bid IS NULL OR NOT (public.has_permission('commerce.manage',bid) OR EXISTS(SELECT 1 FROM public.businesses WHERE id=bid AND owner_id=auth.uid() AND status='approved' AND archived_at IS NULL)) THEN RAISE EXCEPTION 'Redemption denied'; END IF; SELECT count(*) INTO used FROM public.offer_redemptions WHERE offer_id=(payload->>'offer_id')::uuid; IF lim>0 AND used>=lim THEN RAISE EXCEPTION 'Usage limit reached'; END IF; INSERT INTO public.offer_redemptions(offer_id,reference,recorded_by,reason) VALUES((payload->>'offer_id')::uuid,(payload->>'reference')::uuid,auth.uid(),decision_reason) ON CONFLICT(reference) DO NOTHING RETURNING id INTO rid; RETURN rid; END IF;
IF kind='cancel' THEN SELECT business_id INTO bid FROM public.business_subscriptions WHERE id=(payload->>'id')::uuid FOR UPDATE; IF bid IS NULL OR NOT (public.has_permission('commerce.manage',bid) OR EXISTS(SELECT 1 FROM public.businesses WHERE id=bid AND owner_id=auth.uid())) THEN RAISE EXCEPTION 'Cancellation denied'; END IF; UPDATE public.business_subscriptions SET status=CASE WHEN coalesce((payload->>'immediate')::boolean,false) THEN 'cancelled' ELSE status END,cancel_at_end=true,reason=decision_reason WHERE id=(payload->>'id')::uuid RETURNING id INTO rid;
ELSE bid:=nullif(payload->>'business_id','')::uuid; IF NOT public.has_permission('commerce.manage',bid) THEN RAISE EXCEPTION 'Commercial management denied'; END IF;
IF kind='plan' THEN IF payload->'entitlements' ? 'verified' OR payload->'entitlements' ? 'sponsored' THEN RAISE EXCEPTION 'Verification and sponsorship are independent'; END IF; INSERT INTO public.plan_definitions(key,name,price_minor,currency,period_days,entitlements,active) VALUES(payload->>'key',payload->>'name',(payload->>'price_minor')::integer,'INR',(payload->>'period_days')::integer,payload->'entitlements',coalesce((payload->>'active')::boolean,false)) ON CONFLICT(key) DO UPDATE SET name=excluded.name,price_minor=excluded.price_minor,period_days=excluded.period_days,entitlements=excluded.entitlements,active=excluded.active RETURNING id INTO rid;
ELSIF kind='subscription' THEN IF NOT EXISTS(SELECT 1 FROM public.businesses WHERE id=bid AND status='approved' AND archived_at IS NULL) THEN RAISE EXCEPTION 'An approved listing is required'; END IF; PERFORM 1 FROM public.businesses WHERE id=bid FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.plan_definitions WHERE id=(payload->>'plan_id')::uuid AND active) THEN RAISE EXCEPTION 'Active plan required'; END IF; UPDATE public.business_subscriptions SET status='cancelled' WHERE business_id=bid AND status='active'; INSERT INTO public.business_subscriptions(business_id,plan_id,status,starts_at,ends_at,reason,actor_id) VALUES(bid,(payload->>'plan_id')::uuid,'active',(payload->>'starts_at')::timestamptz,(payload->>'ends_at')::timestamptz,decision_reason,auth.uid()) RETURNING id INTO rid;
ELSIF kind='invoice' THEN SELECT business_id INTO bid FROM public.business_subscriptions WHERE id=(payload->>'subscription_id')::uuid; IF bid IS NULL OR NOT public.has_permission('commerce.manage',bid) THEN RAISE EXCEPTION 'Invoice denied'; END IF; INSERT INTO public.commercial_records(subscription_id,reference,amount_minor,status,method,external_reference,reason,recorded_by) VALUES((payload->>'subscription_id')::uuid,payload->>'reference',(payload->>'amount_minor')::integer,payload->>'status','manual',coalesce(payload->>'external_reference',''),decision_reason,auth.uid()) RETURNING id INTO rid; IF payload->>'status'='failed' THEN UPDATE public.business_subscriptions SET status='payment_failed',reason=decision_reason WHERE id=(payload->>'subscription_id')::uuid; END IF;
ELSIF kind='placement' THEN IF NOT EXISTS(SELECT 1 FROM public.businesses WHERE id=bid AND status='approved' AND archived_at IS NULL AND city=payload->>'city' AND (coalesce(payload->>'category','')='' OR category=payload->>'category')) THEN RAISE EXCEPTION 'Placement must match an approved relevant listing'; END IF; INSERT INTO public.sponsored_placements(business_id,city,category,placement,starts_at,ends_at,status,creative,approved,terms,budget_minor) VALUES(bid,payload->>'city',coalesce(payload->>'category',''),payload->>'placement',(payload->>'starts_at')::timestamptz,(payload->>'ends_at')::timestamptz,payload->>'status',payload->>'creative',coalesce((payload->>'approved')::boolean,false),payload->>'terms',coalesce((payload->>'budget_minor')::integer,0)) RETURNING id INTO rid;
ELSIF kind='placement_status' THEN SELECT business_id INTO bid FROM public.sponsored_placements WHERE id=(payload->>'id')::uuid; IF NOT public.has_permission('commerce.manage',bid) THEN RAISE EXCEPTION 'Placement denied'; END IF; UPDATE public.sponsored_placements SET status=payload->>'status' WHERE id=(payload->>'id')::uuid RETURNING id INTO rid;
ELSIF kind='offer' THEN IF NOT EXISTS(SELECT 1 FROM public.businesses WHERE id=bid AND status='approved' AND archived_at IS NULL AND city=payload->>'city') THEN RAISE EXCEPTION 'Offer must match an approved listing'; END IF; INSERT INTO public.merchant_offers(business_id,title,eligibility,terms,city,locality,starts_at,ends_at,usage_limit,approved,status) VALUES(bid,payload->>'title',payload->>'eligibility',payload->>'terms',payload->>'city',coalesce(payload->>'locality',''),(payload->>'starts_at')::timestamptz,(payload->>'ends_at')::timestamptz,coalesce((payload->>'usage_limit')::integer,0),coalesce((payload->>'approved')::boolean,false),payload->>'status') RETURNING id INTO rid;
ELSIF kind='offer_status' THEN SELECT business_id INTO bid FROM public.merchant_offers WHERE id=(payload->>'id')::uuid; IF NOT public.has_permission('commerce.manage',bid) THEN RAISE EXCEPTION 'Offer denied'; END IF; UPDATE public.merchant_offers SET status=payload->>'status' WHERE id=(payload->>'id')::uuid RETURNING id INTO rid;
ELSE RAISE EXCEPTION 'Unknown commercial action'; END IF; END IF;
INSERT INTO public.directory_audit(business_id,entity_id,action,actor_id,after_data,note) VALUES(bid,rid,'commerce.'||kind,auth.uid(),payload,decision_reason); RETURN rid; END; $$;
REVOKE ALL ON FUNCTION public.commerce_action(text,jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.commerce_action(text,jsonb,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.record_placement_event(pid uuid,ek uuid,event_kind text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF event_kind NOT IN ('impression','click') THEN RAISE EXCEPTION 'Unsupported public event'; END IF; IF NOT EXISTS(SELECT 1 FROM public.sponsored_placements p JOIN public.businesses b ON b.id=p.business_id WHERE p.id=pid AND p.approved AND p.status='active' AND p.starts_at<=now() AND p.ends_at>now() AND b.status='approved' AND b.archived_at IS NULL AND b.city=p.city) THEN RETURN; END IF; INSERT INTO public.placement_events(placement_id,event_key,kind) VALUES(pid,ek,event_kind) ON CONFLICT(event_key) DO NOTHING; END; $$;
GRANT EXECUTE ON FUNCTION public.record_placement_event(uuid,uuid,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.resolve_site_redirect(path text) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT published->>'href' FROM public.site_content WHERE kind='redirect' AND published->>'body'=path AND published IS NOT NULL LIMIT 1; $$;
GRANT EXECUTE ON FUNCTION public.resolve_site_redirect(text) TO anon,authenticated;